from pathlib import Path
import os,json,hashlib,gzip,base64,subprocess
R=Path(__file__).resolve().parent;H=Path(os.environ['GARMENT_HOST']).resolve();P=R.parent/'hc-s2-1';PREV=R.parent/'hc-s3-2'
sha=lambda b:hashlib.sha256(b).hexdigest()
a=json.loads((R/'TASK_ANCHOR.json').read_text());x=json.loads((R/'runtime-observation.json').read_text());proof=json.loads((R/'qa/native/CAPTURE_REPORT.json').read_text());files=json.loads((R/'qa/native/SOURCE_FILES.json').read_text())
assert proof['passed'] and proof['runtimeObservationSHA256']==sha((R/'runtime-observation.json').read_bytes())
assert x['source']['repository']==a['source']['repository'] and x['source']['commit']==a['source']['commit'] and x['source']['path']==a['source']['directory']+'/index.html'
assert x['source']['sha256']==sha((H/'index.html').read_bytes())
for n,h in files.items():assert sha((H/n).read_bytes())==h,('SOURCE_CHANGED',n)
manifest=json.loads((H/'BUILD_MANIFEST.json').read_text());assert manifest['version']=='MP05-R10-Studio' and manifest['fullGarmentAccepted'] is False
names=['index.html','app.mjs','BUILD_MANIFEST.json','materials.json','material-settings.mjs','panel-grain.mjs','source-contract.mjs','platform-person.mjs','live-cloth-controller.mjs']
ids=sorted({p['id'] for g in x['pieces'] for p in g['panels']})
node="import(process.argv[1]).then(m=>console.log(JSON.stringify(Object.fromEntries(JSON.parse(process.argv[2]).map(k=>[k,m.grainAxes(k)])))))"
axes=json.loads(subprocess.check_output(['node','-e',node,(H/'panel-grain.mjs').as_uri(),json.dumps(ids)],text=True))
facts={'schema':'kaopu/garment-relation-source-facts@1','source':x['source'],'hostVersion':manifest['version'],'manifest':manifest,'materials':json.loads((H/'materials.json').read_text()),'axes':axes,'connections':json.loads((PREV/'connection-registry.json').read_text()),'sourceFiles':{n:files[n] for n in names},'captureEvidence':{'workflowRun':os.environ.get('CAPTURE_RUN_ID'),'captureSourceCommit':os.environ.get('CAPTURE_SOURCE_COMMIT'),'observationSHA256':sha((R/'runtime-observation.json').read_bytes()),'reportSHA256':sha((R/'qa/native/CAPTURE_REPORT.json').read_bytes())},'originalURL':'https://haihao0307.github.io/guilin-dem-pipeline/'+a['source']['directory']+'/?look=D03','upstreamReview':{'repository':a['source']['repository'],'pullRequest':283,'branch':a['source']['activeBranch'],'branchHeadAtRead':a['source']['branchHeadAtRead'],'status':'dynamic cloth not accepted; this task does not rerun or fix dynamic collision tests'},'live':False,'productionInstalled':False}
(R/'source-facts.json').write_text(json.dumps(facts,ensure_ascii=False,indent=2))
parent=(PREV/'preview.html').read_bytes();pm=json.loads((PREV/'BUILD_MANIFEST.json').read_text());assert sha(parent)==pm['html']['sha256']=='fefe6a5d1ad4b572e1f39a6721c7186a4a03a6a8cdde1433211676f726df5101'
protocol=(P/'protocol.js').read_bytes();blob=hashlib.sha1(b'blob '+str(len(protocol)).encode()+b'\0'+protocol).hexdigest();assert blob=='74e1f859fa2001456286e6a4081ef639124699d2'
compressed=gzip.compress(parent,compresslevel=9,mtime=0);assert gzip.decompress(compressed)==parent
legacy={'encoding':'gzip-base64','bytes':len(parent),'sha256':sha(parent),'data':base64.b64encode(compressed).decode()}
sourceCommit=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();names2=['TASK_ANCHOR.json','capture.js','capture.py','relations.js','panel.html','app.js','build.py','tests/protocol.cjs','tests/browser.py','README.md']
build={'version':'REALITY-HC-S3.3-A','sourceCommit':sourceCommit,'sourceFiles':{n:sha((R/n).read_bytes()) for n in names2},'nativeSource':x['source'],'captureEvidence':facts['captureEvidence'],'captureMode':'frozen_native_runtime_observation_not_current_browser_live','case':'D03:T03+P02; denim-bleach','legacy':{k:v for k,v in legacy.items() if k!='data'},'commonProtocolUnchanged':True,'protocolSHA256':sha(protocol),'originalRuntimeModified':False,'productionInstalled':False,'physicalCertification':False,'fitCertified':False,'userVisualAccepted':False}
js='const RF33_BUILD='+json.dumps(build,ensure_ascii=False)+';\nconst RF33_DICTIONARY='+(P/'measurement-dictionary.json').read_text()+';\nconst RF33_OBSERVATION='+json.dumps(x,ensure_ascii=False)+';\nconst RF33_FACTS='+json.dumps(facts,ensure_ascii=False)+';\nconst RF33_LEGACY='+json.dumps(legacy)+';\n'+protocol.decode()+'\n'+(R/'relations.js').read_text()+'\n'+(R/'app.js').read_text()
assert '</script' not in js.lower();g=R/'_generated';g.mkdir(exist_ok=True);(g/'bundle.js').write_text(js);subprocess.run(['node','--check',str(g/'bundle.js')],check=True)
html=(R/'panel.html').read_text();assert html.count('<!-- RF33_SCRIPTS -->')==1;html=html.replace('<!-- RF33_SCRIPTS -->','<script>\n'+js+'\n</script>');(R/'preview.html').write_text(html);build['html']={'bytes':len(html.encode()),'sha256':sha(html.encode())};(R/'BUILD_MANIFEST.json').write_text(json.dumps(build,ensure_ascii=False,indent=2))
q=R/'qa/source';q.mkdir(parents=True,exist_ok=True);(q/'ASSEMBLY.json').write_text(json.dumps({'passed':True,'nativeSourceUnchanged':True,'sourceFilesVerified':len(files),'legacyRemovalNotRequired':'original S3.2 HTML is embedded as exact bytes, not patched','legacySHA256':sha(parent),'frozenObservationSHA256':facts['captureEvidence']['observationSHA256'],'commonProtocolBlob':blob,'newRenderingOrPhysics':False},indent=2));print(json.dumps({'sourceCommit':sourceCommit,'html':build['html'],'captureEvidence':facts['captureEvidence']},indent=2))
